"""Self-contained gallery of the actual native CAD tessellations."""
import json

def write_gallery(out, data):
    html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Five printable dungeon maps</title><style>
:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#162124;color:#e7e4da;font:14px system-ui,sans-serif}header{padding:27px 36px 23px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #ffffff16}.eyebrow{font-size:10px;letter-spacing:2.4px;color:#dbb57b;text-transform:uppercase;font-weight:650}h1{font:32px Georgia,serif;margin:7px 0}header p{color:#a9b8ad;font-size:12px;margin:6px 0 0}a,button{font:inherit;color:inherit;text-decoration:none}button,a.action{background:#2d3b3e;border:1px solid #ffffff24;padding:10px 14px;border-radius:5px;cursor:pointer}.actions{display:flex;gap:9px;align-items:center}.actions .primary{background:#d6ae72;color:#172125;font-weight:700;border:0}.tabs{display:flex;gap:3px;background:#101c1f;padding:4px;border-radius:6px}.tabs button{background:none;border:0;font-size:12px;padding:9px 13px;color:#aabbaf}.tabs button.active{background:#3d4a4a;color:#f0e8d9}.grid{padding:24px 32px;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.card{border:1px solid #ffffff1b;background:#1d2b2e;border-radius:8px;overflow:hidden;position:relative}.card canvas{display:block;width:100%;height:270px;background:radial-gradient(ellipse,#354347,#223135 70%,#1d2b2e);cursor:grab;touch-action:none}.card canvas:active{cursor:grabbing}.card img{width:100%;height:270px;object-fit:contain;display:none}.number{position:absolute;top:14px;left:16px;color:#c1b695;font-size:11px;letter-spacing:2px;pointer-events:none}.info{padding:15px 17px 17px;border-top:1px solid #ffffff0d}.info h2{font:21px Georgia,serif;margin:0 0 5px}.info p{font-size:11px;color:#9cafaa;margin:0 0 14px;line-height:1.5;min-height:17px}.links{display:flex;gap:13px;align-items:center;font-size:11px}.links a{color:#d3b783}.size{margin-left:auto;color:#8faaa0;font-size:10px}.guide{padding:27px;background:linear-gradient(135deg,#253638,#1c2a2e);display:flex;flex-direction:column;justify-content:center}.guide h2{font:26px Georgia,serif;margin:10px 0 18px}.guide p{color:#aebbb0;line-height:1.8;font-size:12px;margin:0 0 16px}.facts{display:grid;grid-template-columns:1fr 1fr;gap:15px;border-top:1px solid #ffffff16;padding-top:18px}.facts b{display:block;font:24px Georgia,serif;color:#e6dcc7}.facts span{font-size:10px;color:#9aaca1}footer{padding:0 34px 22px;color:#8fa59b;font-size:10px;display:flex;justify-content:space-between;gap:20px}dialog{padding:0;max-width:1160px;width:92vw;background:#1d2b2e;color:#e8e0d1;border:1px solid #ffffff30;border-radius:8px}dialog::backdrop{background:#061014dc}dialog .bar{padding:17px 22px;display:flex;justify-content:space-between;align-items:center}dialog h2{font:26px Georgia,serif;margin:0}dialog canvas{width:100%;height:min(68vh,700px);display:block;touch-action:none;background:radial-gradient(ellipse,#354347,#1b292d);cursor:grab}.modal-footer{display:flex;justify-content:space-between;padding:17px 22px;font-size:12px;color:#b2c2b5}.close{font-size:19px;padding:4px 11px}.pill{font-size:10px;letter-spacing:1px;color:#adc5b2}@media(min-width:1600px){.card canvas{height:320px}}@media(max-width:950px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}header{align-items:flex-start;gap:15px}.actions{flex-wrap:wrap;justify-content:flex-end}h1{font-size:26px}}@media(max-width:640px){header{padding:20px;display:block}.actions{margin-top:18px;justify-content:flex-start}.grid{grid-template-columns:1fr;padding:18px}.card canvas{height:300px}footer{padding:0 20px 20px;display:block}}
</style></head><body><header><div><div class="eyebrow">Printable tabletop maps · built through MCP</div><h1>Five ways into the dungeon</h1><p>Different encounters. A shared 1-inch grid. Actual CAD geometry.</p></div><div class="actions"><div class="tabs"><button data-view="iso" class="active">Isometric</button><button data-view="top">Top plans</button></div><a class="action primary" href="printable-dungeon-maps.zip" download>Download all five ↓</a></div></header><main class="grid" id="grid"></main><footer><span>All five maps: valid CAD, one connected solid, closed STL meshes. Colors suggest paint; STLs contain geometry only.</span><span>Print supports and physical fit remain untested.</span></footer><dialog id="detail"><div class="bar"><h2 id="title"></h2><button class="close" aria-label="Close preview">×</button></div><canvas id="large" aria-label="Interactive map preview"></canvas><div class="modal-footer"><span id="dimensions"></span><span>Drag to orbit · scroll to zoom</span><a id="stl" download>Download STL ↓</a></div></dialog><script>
const maps=__MAPS__;
let mode='iso';const renderers=[];
function renderer(canvas,map){const gl=canvas.getContext('webgl',{alpha:true,antialias:true,preserveDrawingBuffer:true});if(!gl)return null;let yaw=-Math.PI/4,pitch=-.95,zoom=1,drag=null;
function shader(type,source){const s=gl.createShader(type);gl.shaderSource(s,source);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(s));return s;}
const program=gl.createProgram();gl.attachShader(program,shader(gl.VERTEX_SHADER,`attribute vec3 p;attribute vec3 n;attribute vec4 color;uniform mat3 rotation;uniform vec2 scale;varying vec3 normal;varying vec4 c;void main(){vec3 q=rotation*p;gl_Position=vec4(q.xy*scale,-q.z*.6,1.);normal=n;c=color;}`));gl.attachShader(program,shader(gl.FRAGMENT_SHADER,`precision mediump float;varying vec3 normal;varying vec4 c;void main(){vec3 N=normalize(normal);if(!gl_FrontFacing)N=-N;float key=max(dot(N,normalize(vec3(-.4,-.65,1.))),0.);float fill=max(dot(N,normalize(vec3(.8,.4,.7))),0.);vec3 light=vec3(.43,.45,.46)+key*vec3(.48,.44,.35)+fill*vec3(.13,.15,.17);gl_FragColor=vec4(mix(c.rgb*light,c.rgb*1.05,c.a),1.);}`));gl.linkProgram(program);gl.useProgram(program);gl.enable(gl.DEPTH_TEST);
const lo=[0,1,2].map(i=>Math.min(...map.parts.map(p=>p.bounds[0][i]))),hi=[0,1,2].map(i=>Math.max(...map.parts.map(p=>p.bounds[1][i]))),center=lo.map((v,i)=>(v+hi[i])/2),span=Math.max(...hi.map((v,i)=>v-lo[i])),values={p:[],n:[],color:[]};
for(const part of map.parts){const rgb=part.color.match(/[a-f0-9]{2}/gi).map(x=>parseInt(x,16)/255);for(const t of part.triangles){const p=t.points,a=p[1].map((v,i)=>v-p[0][i]),b=p[2].map((v,i)=>v-p[0][i]),n=[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]],length=Math.hypot(...n)||1;const variation=.96+.04*Math.sin(t.face*17.3);for(const point of p){values.p.push(...point.map((v,i)=>(v-center[i])/span));values.n.push(...n.map(v=>v/length));values.color.push(...rgb.map(v=>v*variation),part.group==='flames'?1:0);}}}
for(const key of Object.keys(values)){const buffer=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,buffer);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(values[key]),gl.STATIC_DRAW);const index=gl.getAttribLocation(program,key);gl.enableVertexAttribArray(index);gl.vertexAttribPointer(index,key==='color'?4:3,gl.FLOAT,false,0,0);}
function rotation(){const c=Math.cos(yaw),s=Math.sin(yaw),cp=Math.cos(pitch),sp=Math.sin(pitch);return[c,cp*s,sp*s,-s,cp*c,sp*c,0,-sp,cp];}
function draw(){const rect=canvas.getBoundingClientRect();if(!rect.width||!rect.height)return;const ratio=Math.min(devicePixelRatio,2);canvas.width=rect.width*ratio;canvas.height=rect.height*ratio;gl.viewport(0,0,canvas.width,canvas.height);gl.clearColor(0,0,0,0);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);const r=rotation(),xs=[],ys=[];for(const x of [lo[0],hi[0]])for(const y of [lo[1],hi[1]])for(const z of [lo[2],hi[2]]){const p=[x,y,z].map((v,i)=>(v-center[i])/span);xs.push(r[0]*p[0]+r[3]*p[1]+r[6]*p[2]);ys.push(r[1]*p[0]+r[4]*p[1]+r[7]*p[2]);}const aspect=rect.width/rect.height,scale=zoom*Math.min(1.72/(Math.max(...ys)-Math.min(...ys)),1.72*aspect/(Math.max(...xs)-Math.min(...xs)));gl.uniformMatrix3fv(gl.getUniformLocation(program,'rotation'),false,new Float32Array(r));gl.uniform2f(gl.getUniformLocation(program,'scale'),scale/aspect,scale);gl.drawArrays(gl.TRIANGLES,0,values.p.length/3);}
function view(next){yaw=next==='top'?0:-Math.PI/4;pitch=next==='top'?0:-.95;zoom=1;draw();}
canvas.onpointerdown=e=>{drag=[e.clientX,e.clientY];canvas.setPointerCapture(e.pointerId);};canvas.onpointermove=e=>{if(!drag)return;yaw+=(e.clientX-drag[0])*.008;pitch=Math.max(-1.5,Math.min(.05,pitch+(e.clientY-drag[1])*.008));drag=[e.clientX,e.clientY];draw();};canvas.onpointerup=()=>drag=null;canvas.onpointercancel=()=>drag=null;canvas.addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(.6,Math.min(2.2,zoom*Math.exp(-e.deltaY*.001)));draw();},{passive:false});window.addEventListener('resize',draw);view(mode);return{view,draw};}
const grid=document.querySelector('#grid');let large=null;
for(const [i,map] of maps.entries()){const card=document.createElement('article');card.className='card';card.innerHTML=`<span class="number">0${i+1}</span><canvas aria-label="${map.title} 3D preview"></canvas><img alt="${map.title} native render" src="${map.slug}/iso.png"><div class="info"><h2>${map.title}</h2><p>${map.description}</p><div class="links"><a href="?map=${map.slug}" data-open>Explore 3D ↗</a><a href="${map.slug}/map.stl" download>STL ↓</a><a href="${map.slug}/map.step" download>STEP ↓</a><span class="size">${map.size}</span></div></div>`;grid.append(card);const canvas=card.querySelector('canvas'),r=renderer(canvas,map);if(r)renderers.push(r);else{canvas.style.display='none';card.querySelector('img').style.display='block';}card.querySelector('[data-open]').onclick=e=>{e.preventDefault();openMap(map);};}
const guide=document.createElement('article');guide.className='card guide';guide.innerHTML=`<div class="eyebrow">Shared scale · different stories</div><h2>Built to bring to the table.</h2><p>Open tops keep encounters visible. Flat bases keep the maps together. Every layout is available as an editable CAD model and a single-piece STL.</p><div class="facts"><div><b>25.4 mm</b><span>square grid</span></div><div><b>5 maps</b><span>five connected solids</span></div><div><b>&lt; 220 mm</b><span>maximum width and depth</span></div><div><b>STL + STEP</b><span>plus editable model JSON</span></div></div><p style="margin-top:19px;margin-bottom:0"><a href="README.md">Read the print notes →</a></p>`;grid.append(guide);
function openMap(map){document.querySelector('#title').textContent=map.title;document.querySelector('#dimensions').textContent=map.dimensions_mm.map(n=>n.toFixed(1)).join(' × ')+' mm · '+map.size;document.querySelector('#stl').href=map.slug+'/map.stl';document.querySelector('#detail').showModal();const old=document.querySelector('#large'),next=old.cloneNode();old.replaceWith(next);large=renderer(next,map);if(large)large.view(mode);}
document.querySelector('.close').onclick=()=>document.querySelector('#detail').close();document.querySelectorAll('[data-view]').forEach(button=>button.onclick=()=>{mode=button.dataset.view;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b===button));for(const r of renderers)r.view(mode);if(large)large.view(mode);});const query=new URLSearchParams(location.search);if(query.get('view')==='top')document.querySelector('[data-view="top"]').click();if(query.has('map')){const map=maps.find(m=>m.slug===query.get('map'));if(map)openMap(map);}window.mapGallery={maps:maps.map(m=>m.slug),renderers:renderers.length};
</script></body></html>'''
    (out/'index.html').write_text(html.replace('__MAPS__',json.dumps(data,separators=(',',':'))))
